#!/usr/bin/env bash
set -e
cd ~/robie_ws
mkdir -p src/robie_vision/scripts src/robie_vision/systemd src/robie_vision/config src/robie_vision/launch src/robie_vision/robie_vision
cp ~/picam-control/scripts/stream_start.sh src/robie_vision/scripts/ || true
cp ~/picam-control/scripts/capture.sh src/robie_vision/scripts/ || true
cp ~/picam-control/scripts/view_stream.sh src/robie_vision/scripts/ || true
cp ~/picam-control/systemd/wifi-powersave-off.service src/robie_vision/systemd/ || true
chmod +x src/robie_vision/scripts/*.sh || true
touch src/robie_vision/robie_vision/__init__.py
printf '%s\n' "camera:" " width: 640" " height: 480" " framerate: 30" " quality: 50" " denoise: 'cdn_off'" "" "stream:" " port: 8888" " host: '0.0.0.0'" "" "detection:" " threshold: 127" " min_area: 500" " confidence_threshold: 0.6" "" "output:" " captures_dir: 'captures'" " logs_dir: 'logs'" > src/robie_vision/config/camera.yaml
printf '%s\n' "<?xml version='1.0'?>" "<?xml-model href='http://download.ros.org/schema/package_format3.xsd' schematypens='http://www.w3.org/2001/XMLSchema'?>" "<package format='3'>" " <name>robie_vision</name>" " <version>0.1.0</version>" " <description>Camera and vision processing for R.O.B.I.E.</description>" " <maintainer email='keneayogu@gmail.com'>th0r12f4t</maintainer>" " <license>MIT</license>" " <buildtool_depend>ament_python</buildtool_depend>" " <depend>rclpy</depend>" " <depend>sensor_msgs</depend>" " <depend>std_msgs</depend>" " <depend>cv_bridge</depend>" " <test_depend>ament_copyright</test_depend>" " <test_depend>ament_flake8</test_depend>" " <test_depend>ament_pep257</test_depend>" " <test_depend>python3-pytest</test_depend>" " <export>" " <build_type>ament_python</build_type>" " </export>" "</package>" > src/robie_vision/package.xml
printf '%s\n' "from setuptools import setup" "import os" "from glob import glob" "" "package_name = 'robie_vision'" "" "setup(" " name=package_name," " version='0.1.0'," " packages=[package_name]," " data_files=[" " ('share/ament_index/resource_index/packages'," " ['resource/' + package_name])," " ('share/' + package_name, ['package.xml'])," " (os.path.join('share', package_name, 'launch'), glob('launch/*.py'))," " (os.path.join('share', package_name, 'config'), glob('config/*.yaml'))," " ]," " install_requires=['setuptools']," " zip_safe=True," " maintainer='th0r12f4t'," " maintainer_email='keneayogu@gmail.com'," " description='Camera and vision processing for R.O.B.I.E.'," " license='MIT'," " tests_require=['pytest']," " entry_points={" " 'console_scripts': [" " 'camera_node = robie_vision.camera_node:main'," " 'crack_detector_node = robie_vision.crack_detector_node:main'," " ]," " }," ")" > src/robie_vision/setup.py
printf '%s\n' "from launch import LaunchDescription" "from launch_ros.actions import Node" "" "CONFIG = '/home/th0r12f4t/robie_ws/src/robie_vision/config/camera.yaml'" "" "" "def generate_launch_description():" " return LaunchDescription([" " Node(" " package='robie_vision'," " executable='camera_node'," " name='camera_node'," " output='screen'," " parameters=[{'config_path': CONFIG}]," " )," " Node(" " package='robie_vision'," " executable='crack_detector_node'," " name='crack_detector_node'," " output='screen'," " parameters=[{'config_path': CONFIG}]," " )," " ])" > src/robie_vision/launch/vision.launch.py
printf '%s\n' "# camera_node: wraps rpicam-vid MJPEG stream, publishes sensor_msgs/Image" "import subprocess" "import time" "import rclpy" "from rclpy.node import Node" "from sensor_msgs.msg import Image" "from cv_bridge import CvBridge" "import cv2" "import yaml" "" "CONFIG_PATH = '/home/th0r12f4t/robie_ws/src/robie_vision/config/camera.yaml'" "" "class CameraNode(Node):" " def __init__(self):" " super().__init__('camera_node')" " with open(CONFIG_PATH, 'r') as f:" " self.config = yaml.safe_load(f)" " cam = self.config['camera']" " stream = self.config['stream']" " self.bridge = CvBridge()" " self.pub = self.create_publisher(Image, '/camera/image_raw', 10)" " port = int(stream['port'])" > src/robie_vision/robie_vision/camera_node.py
printf '%s\n' " cmd = ['rpicam-vid', '-t', '0', '-n', '--codec', 'mjpeg'," " '--width', str(cam['width']), '--height', str(cam['height'])," " '--framerate', str(cam['framerate']), '--quality', str(cam['quality'])," " '--denoise', str(cam['denoise']), '--flush', '--listen'," " '-o', 'tcp://0.0.0.0:' + str(port)]" " self.proc = subprocess.Popen(cmd)" " self.get_logger().info('started rpicam-vid on port %d' % port)" " time.sleep(3.0)" " self.cap = cv2.VideoCapture('tcp://127.0.0.1:' + str(port))" " if not self.cap.isOpened():" " self.get_logger().error('cannot open camera stream')" " else:" " self.get_logger().info('camera stream open')" " period = 1.0 / max(1.0, float(cam['framerate']))" " self.create_timer(period, self.tick)" " def tick(self):" " if not self.cap.isOpened():" " return" " ok, frame = self.cap.read()" " if not ok:" " self.get_logger().warn('frame read failed')" " return" >> src/robie_vision/robie_vision/camera_node.py
printf '%s\n' " rgb = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)" " msg = self.bridge.cv2_to_imgmsg(rgb, encoding='rgb8')" " msg.header.stamp = self.get_clock().now().to_msg()" " msg.header.frame_id = 'camera_frame'" " self.pub.publish(msg)" " def destroy_node(self):" " try:" " self.cap.release()" " except Exception:" " pass" " try:" " self.proc.terminate()" " except Exception:" " pass" " super().destroy_node()" "" "def main(args=None):" " rclpy.init(args=args)" " node = CameraNode()" " try:" " rclpy.spin(node)" " except KeyboardInterrupt:" " pass" " finally:" " node.destroy_node()" " rclpy.shutdown()" "" "if __name__ == '__main__':" " main()" >> src/robie_vision/robie_vision/camera_node.py
printf '%s\n' "# crack_detector_node: classical CV pipeline, publishes C,conf,x,y events" "import rclpy" "from rclpy.node import Node" "from sensor_msgs.msg import Image" "from std_msgs.msg import String" "from cv_bridge import CvBridge" "import cv2" "import numpy as np" "import yaml" "" "CONFIG_PATH = '/home/th0r12f4t/robie_ws/src/robie_vision/config/camera.yaml'" "" "class CrackDetectorNode(Node):" " def __init__(self):" " super().__init__('crack_detector_node')" " with open(CONFIG_PATH, 'r') as f:" " self.config = yaml.safe_load(f)" " det = self.config['detection']" " self.min_area = float(det['min_area'])" " self.conf_thresh = float(det['confidence_threshold'])" " self.bridge = CvBridge()" " self.sub = self.create_subscription(Image, '/camera/image_raw', self.on_image, 10)" " self.ev_pub = self.create_publisher(String, '/robie/event', 10)" " self.an_pub = self.create_publisher(Image, '/camera/image_annotated', 10)" " self.get_logger().info('crack detector ready')" > src/robie_vision/robie_vision/crack_detector_node.py
printf '%s\n' " def on_image(self, msg):" " try:" " rgb = self.bridge.imgmsg_to_cv2(msg, desired_encoding='rgb8')" " except Exception as e:" " self.get_logger().error('bridge error: %s' % str(e))" " return" " gray = cv2.cvtColor(rgb, cv2.COLOR_RGB2GRAY)" " thresh = cv2.adaptiveThreshold(gray, 255, cv2.ADAPTIVE_THRESH_GAUSSIAN_C, cv2.THRESH_BINARY_INV, 11, 2)" " kernel = np.ones((3, 3), np.uint8)" " cleaned = cv2.morphologyEx(thresh, cv2.MORPH_CLOSE, kernel, iterations=2)" " cleaned = cv2.morphologyEx(cleaned, cv2.MORPH_OPEN, kernel, iterations=1)" " edges = cv2.Canny(cleaned, 50, 150)" " contours, _ = cv2.findContours(edges, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)" " annotated = rgb.copy()" " best = None" " for c in contours:" " area = cv2.contourArea(c)" " if area < self.min_area:" " continue" " x, y, w, h = cv2.boundingRect(c)" " ar = float(w) / float(h) if h > 0 else 0.0" " conf = min(1.0, area / 10000.0)" " if ar < 0.1 or ar > 10.0:" " conf = conf * 0.5" " if conf < self.conf_thresh:" " continue" >> src/robie_vision/robie_vision/crack_detector_node.py
printf '%s\n' " nx = (x + w / 2.0) / float(rgb.shape[1])" " ny = (y + h / 2.0) / float(rgb.shape[0])" " if best is None or conf > best[0]:" " best = (conf, nx, ny)" " cv2.rectangle(annotated, (x, y), (x + w, y + h), (255, 0, 0), 2)" " am = self.bridge.cv2_to_imgmsg(annotated, encoding='rgb8')" " am.header = msg.header" " self.an_pub.publish(am)" " if best is not None:" " em = String()" " em.data = 'C,%.2f,%.2f,%.2f' % best" " self.ev_pub.publish(em)" " self.get_logger().info('crack event: %s' % em.data)" "" "def main(args=None):" " rclpy.init(args=args)" " node = CrackDetectorNode()" " try:" " rclpy.spin(node)" " except KeyboardInterrupt:" " pass" " finally:" " node.destroy_node()" " rclpy.shutdown()" "" "if __name__ == '__main__':" " main()" >> src/robie_vision/robie_vision/crack_detector_node.py
python3 -m py_compile src/robie_vision/robie_vision/camera_node.py src/robie_vision/robie_vision/crack_detector_node.py src/robie_vision/launch/vision.launch.py
echo COMPILE_OK
python3 -c "import yaml; d=yaml.safe_load(open('src/robie_vision/config/camera.yaml')); print('YAML_OK port', d['stream']['port'])"
source /opt/ros/humble/setup.bash
colcon build --packages-select robie_vision
source install/setup.bash
python3 -c "import cv2; print('CV2_OK', cv2.__version__)" || echo WARN_NO_CV2
python3 -c "import cv_bridge; print('CV_BRIDGE_OK')" || echo WARN_NO_CV_BRIDGE
echo INTEGRATION_COMPLETE
echo NEXT_STEP: ros2 launch robie_vision vision.launch.py
